options.customCss:
:root {
  /* ── Paleta institucional Politécnico Jaime Isaza Cadavid ── */
  --poli-verde:        #009045;
  --poli-verde-dark:   #007a3a;
  --poli-verde-darker: #006631;
  --poli-azul:         #1448A5;
  --poli-azul-dark:    #103a84;
  --poli-blanco:       #ffffff;
  --poli-gris-claro:   #f2f4f8;
  --poli-gris-medio:   #e6e9f1;
  --poli-gris-100:     #c2c5cc;
  --poli-texto:        #1a1c23;

  /* ── Variables del chat engine (n8n) ── */
  --chat--color-primary:            var(--poli-verde);
  --chat--color-primary-shade-50:   var(--poli-verde-dark);
  --chat--color-primary-shade-100:  var(--poli-verde-darker);
  --chat--color-secondary:          var(--poli-azul);
  --chat--color-secondary-shade-50: var(--poli-azul-dark);
  --chat--color-white:              var(--poli-blanco);
  --chat--color-light:              var(--poli-gris-claro);
  --chat--color-light-shade-50:     var(--poli-gris-medio);
  --chat--color-light-shade-100:    var(--poli-gris-100);
  --chat--color-medium:             #d2d4d9;
  --chat--color-dark:               var(--poli-texto);
  --chat--color-disabled:           #d2d4d9;
  --chat--color-typing:             var(--poli-verde);

  /* ── Layout ── */
  --chat--spacing:            1rem;
  --chat--border-radius:      0.625rem;
  --chat--transition-duration: 0.16s;
  --chat--font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  /* ── Ventana ── */
  --chat--window--width:         420px;
  --chat--window--height:        640px;
  --chat--window--bottom:        var(--chat--spacing);
  --chat--window--right:         var(--chat--spacing);
  --chat--window--z-index:       9999;
  --chat--window--border:        1px solid var(--poli-gris-medio);
  --chat--window--border-radius: var(--chat--border-radius);

  /* ── Header ── */
  --chat--header-height:         auto;
  --chat--header--padding:       var(--chat--spacing) 1.25rem;
  --chat--header--background:    linear-gradient(135deg, var(--poli-verde-darker) 0%, var(--poli-verde) 55%, var(--poli-verde-dark) 100%);
  --chat--header--color:         var(--poli-blanco);
  --chat--header--border-top:    none;
  --chat--header--border-bottom: 3px solid var(--poli-azul);
  --chat--header--border-left:   none;
  --chat--header--border-right:  none;
  --chat--heading--font-size:    1.15em;
  --chat--subtitle--font-size:   0.85rem;
  --chat--subtitle--line-height: 1.7;

  /* ── Mensajes ── */
  --chat--message--font-size:    0.95rem;
  --chat--message--padding:      0.75rem 1rem;
  --chat--message--border-radius: var(--chat--border-radius);
  --chat--message-line-height:   1.55;
  --chat--message--margin-bottom: 0.75rem;

  /* Bot */
  --chat--message--bot--background: var(--poli-blanco);
  --chat--message--bot--color:      var(--poli-texto);
  --chat--message--bot--border:     1px solid var(--poli-gris-medio);

  /* Usuario */
  --chat--message--user--background: var(--poli-azul);
  --chat--message--user--color:      var(--poli-blanco);
  --chat--message--user--border:     none;

  --chat--message--pre--background: rgba(0,0,0,0.05);
  --chat--messages-list--padding:    var(--chat--spacing);

  /* ── Toggle flotante ── */
  --chat--toggle--size:               62px;
  --chat--toggle--width:              var(--chat--toggle--size);
  --chat--toggle--height:             var(--chat--toggle--size);
  --chat--toggle--border-radius:      50%;
  --chat--toggle--background:         var(--poli-verde);
  --chat--toggle--hover--background:  var(--poli-verde-dark);
  --chat--toggle--active--background: var(--poli-verde-darker);
  --chat--toggle--color:              var(--poli-blanco);

  /* ── Input ── */
  --chat--textarea--height:            52px;
  --chat--textarea--max-height:        28rem;
  --chat--input--font-size:            inherit;
  --chat--input--border:               0;
  --chat--input--border-radius:        0;
  --chat--input--padding:              1rem;
  --chat--input--background:           var(--poli-blanco);
  --chat--input--text-color:           var(--poli-texto);
  --chat--input--line-height:          1.5;
  --chat--input--border-active:        0;
  --chat--input--left--panel--width:   2rem;

  /* ── Botones ── */
  --chat--button--color:             var(--poli-gris-claro);
  --chat--button--background:        var(--poli-verde);
  --chat--button--padding:           0.5rem 1rem;
  --chat--button--border-radius:     var(--chat--border-radius);
  --chat--button--hover--color:      var(--poli-gris-claro);
  --chat--button--hover--background: var(--poli-verde-dark);
  --chat--close--button--color-hover: var(--poli-blanco);

  /* Enviar */
  --chat--input--send--button--background:       var(--poli-blanco);
  --chat--input--send--button--color:            var(--poli-verde);
  --chat--input--send--button--background-hover: var(--poli-gris-claro);
  --chat--input--send--button--color-hover:      var(--poli-verde-dark);

  /* Adjunto */
  --chat--input--file--button--background:       var(--poli-blanco);
  --chat--input--file--button--color:            var(--poli-azul);
  --chat--input--file--button--background-hover: var(--poli-gris-claro);
  --chat--input--file--button--color-hover:      var(--poli-azul-dark);
  --chat--files-spacing: 0.25rem;

  /* ── Cuerpo y footer ── */
  --chat--body--background:   var(--poli-gris-claro);
  --chat--footer--background: var(--poli-blanco);
  --chat--footer--color:      var(--poli-texto);
}

/* Ancho máximo del globo de mensaje */
.chat-message {
  max-width: 80%;
}

/* Acento verde en mensajes del bot */
.chat-message.from-bot,
.chat-message.bot,
.chat-message.from-assistant {
  border-left: 3px solid var(--poli-verde) !important;
}

/* Responsive mobile */
@media (max-width: 768px) {
  :root {
    --chat--window--width:  100vw;
    --chat--window--height: 100dvh;
  }
  .chat-window {
    border-radius: 0 !important;
    border: none !important;
  }
}
